{"code": "import itertools, math
from collections import defaultdict
G=defaultdict(list)
for r in load_lab():
 if r['family']=='bigram_lm' and math.isfinite(r['mean']) and not r.get('excluded'): G[r['set_id']].append(r)
S=defaultdict(list)
for sid,rs in G.items():
 seen=set()
 for a,b in itertools.combinations(rs,2):
  if a['optimizer']!=b['optimizer'] or a['loss']!=b['loss']: continue
  key=tuple(sorted((a['candidate_id'],b['candidate_id'])))
  if key in seen: continue
  seen.add(key)
  o=a['optimizer']; T=a['budget']['training_steps']; delta=o['lr']*T*(.003/(1-o.get('momentum',0)) if o['type']=='SGD' else 1)
  reg=('sgd' if o['type']=='SGD' else 'adaptive')+('low' if delta<.02 else 'high')
  if a['model_type']!=b['model_type']:
   gru=a if a['model_type']=='gru_lm' else b; tf=b if gru is a else a
   S[(reg,'gru')].append((gru['mean']<tf['mean'],sid))
  elif a['model_type']=='transformer_lm':
   if a['d_model']!=b['d_model']:
    w=a if a['d_model']>b['d_model'] else b; n=b if w is a else a
    S[(reg,'wider_mixed')].append((w['mean']<n['mean'],sid))
   for axis,other in [('d_model',['num_layers','num_heads','d_ff']),('num_layers',['d_model','num_heads','d_ff']),('d_ff',['d_model','num_layers','num_heads'])]:
    if a[axis]!=b[axis] and all(a[x]==b[x] for x in other):
     w=a if a[axis]>b[axis] else b; n=b if w is a else a
     S[(reg,axis)].append((w['mean']<n['mean'],sid))
for k,v in sorted(S.items()): print(k,'wins',sum(x[0] for x in v),'n',len(v),'sets',len(set(x[1] for x in v)))"}

